for n in 0013; do     in="train/data${n}.aselmdb";     out="train_passed/data${n}.aselmdb";     rej="train_rejected/data${n}.aselmdb";     log="train_passed/.logs/data${n}.log";      rm -f "$out" "$out-lock" "$rej" "$rej-lock";     mkdir -p "$(dirname "$out")" "$(dirname "$rej")" "$(dirname "$log")";      echo "Filtering $in ...";     python filter_lmdb.py "$in" -o "$out" --rejected "$rej" --scale 0.35         2>&1 | tee "$log"; done
